-- Additive onboarding journal. Runtime receives only closed protocol commands.
DO $$ DECLARE tab text; name text; definition text; BEGIN
 FOREACH tab IN ARRAY ARRAY['event','event_identity'] LOOP
  name:=CASE WHEN tab='event' THEN 'event_event_code_check' ELSE 'event_identity_event_code_check' END;
  SELECT pg_get_constraintdef(oid) INTO STRICT definition FROM pg_constraint WHERE conrelid=('audit.'||tab)::regclass AND conname=name;
  EXECUTE format('ALTER TABLE audit.%I DROP CONSTRAINT %I',tab,name);
  EXECUTE format('ALTER TABLE audit.%I ADD CONSTRAINT %I CHECK ((%s) OR event_code IN (''PLATFORM_USER_CREATED'',''PLATFORM_USER_ACTIVATED'',''PLATFORM_ACCESS_CHANGED''))',tab,name,substring(definition from 8 for length(definition)-8));
 END LOOP;
END $$;
CREATE TABLE public.platform_member_operation (
 id uuid PRIMARY KEY,
 organization_id uuid NOT NULL REFERENCES public.organization(id),
 requested_by uuid NOT NULL REFERENCES public.global_user(id),
 request_key uuid NOT NULL,
 intent_digest text NOT NULL CHECK(intent_digest ~ '^[a-f0-9]{64}$'),
 input jsonb NOT NULL CHECK(jsonb_typeof(input)='object'),
 global_user_id uuid NOT NULL,
 membership_id uuid NOT NULL UNIQUE,
 profile_code text NOT NULL CHECK(profile_code IN ('ORG_ADMIN','FUNDING_MANAGER','CONTRIBUTOR')),
 phase text NOT NULL DEFAULT 'IDENTITY' CHECK(phase IN ('IDENTITY','PROJECTION','READY','COMPLETE')),
 status text NOT NULL DEFAULT 'WAITING' CHECK(status IN ('WAITING','RUNNING','FAILED','COMPLETE')),
 receipt jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(receipt)='object'),
 fence bigint NOT NULL DEFAULT 0 CHECK(fence>=0),
 lease_until timestamptz,
 revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
 error_code text CHECK(error_code='EXTERNAL_STEP_UNCONFIRMED'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(requested_by,request_key),
 CHECK((status='COMPLETE')=(phase='COMPLETE')),
 CHECK((status='RUNNING')=(lease_until IS NOT NULL))
);
CREATE TABLE public.platform_member_invitation (
 id uuid PRIMARY KEY,
 operation_id uuid NOT NULL REFERENCES public.platform_member_operation(id),
 request_key uuid NOT NULL,
 issued_by uuid NOT NULL REFERENCES public.global_user(id),
 digest text NOT NULL UNIQUE CHECK(digest ~ '^[a-f0-9]{64}$'),
 replace_requested boolean NOT NULL,
 status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','REVOKED','USED')),
 revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
 expires_at timestamptz NOT NULL,
 accepted_at timestamptz,
 exchange_digest text UNIQUE CHECK(exchange_digest ~ '^[a-f0-9]{64}$'),
 binding_digest text CHECK(binding_digest ~ '^[a-f0-9]{64}$'),
 exchange_until timestamptz,
 verified_identity jsonb CHECK(jsonb_typeof(verified_identity)='object'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(operation_id,request_key),
 CHECK(expires_at>created_at),
 CHECK((status='USED')=(accepted_at IS NOT NULL)),
 CHECK((exchange_digest IS NULL)=(binding_digest IS NULL)),
 CHECK((exchange_digest IS NULL)=(exchange_until IS NULL))
);
CREATE UNIQUE INDEX platform_member_one_open_invitation ON public.platform_member_invitation(operation_id) WHERE status='OPEN';
ALTER TABLE public.platform_member_operation OWNER TO c4g_authority_owner;
ALTER TABLE public.platform_member_invitation OWNER TO c4g_authority_owner;
REVOKE ALL ON public.platform_member_operation,public.platform_member_invitation FROM PUBLIC,c4g_central_runtime,c4g_authority_runtime;
GRANT SELECT,INSERT ON public.auth_identity_ref TO c4g_authority_owner;
GRANT INSERT ON public.global_user,public.organization,public.organization_membership TO c4g_authority_owner;
GRANT SELECT,UPDATE ON public.platform_admin_assignment,public.auth_identity_ref,public.tenant,public.organization_provisioning,public.tenant_workload_binding,public.organization_connection,public.tenant_schema_state TO c4g_authority_owner;

CREATE UNIQUE INDEX platform_member_pending_email ON public.platform_member_operation(organization_id,(input->>'adminEmail')) WHERE phase<>'COMPLETE';

CREATE OR REPLACE FUNCTION authority_api.execute(query_code text, parameters text[], final_permit text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $authority$
DECLARE statement text; parameter_count integer; i integer; result_rows jsonb; affected bigint; guard_digest text; previous_permit text;
BEGIN
 IF session_user<>'c4g_authority_runtime' THEN RAISE EXCEPTION 'AUTHORITY_LOGIN_REQUIRED' USING ERRCODE='42501'; END IF;
 CASE query_code
 WHEN 'cfdf25282fa6ecb5642067881242443941f22bdc2848486fea92d7d33bd5071d' THEN statement:='SELECT * FROM public.platform_member_operation WHERE id=$1 FOR UPDATE';
 WHEN '1cda4d0588f633d74627bbf93ce19e4273bcf562b48db29608e15c4e905438bd' THEN statement:='SELECT * FROM public.platform_member_operation WHERE requested_by=$1 AND request_key=$2 FOR UPDATE';
 WHEN '32773aa64377a67cdff83dfdaa2c56d732e2e95d1d1f20f495d40e9862ac4b06' THEN statement:='SELECT id,organization_id,phase,status,revision,error_code,created_at,input,profile_code FROM public.platform_member_operation WHERE organization_id=$1 ORDER BY created_at DESC,id DESC LIMIT 100';
 WHEN '2fcd7b67644da1004a68368d83afb5e2d833d75507c839bc2804ab9fbec6b2c4' THEN statement:='INSERT INTO public.platform_member_operation(id,organization_id,requested_by,request_key,intent_digest,input,global_user_id,membership_id,profile_code) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *';
 WHEN '1fc7c660ee91332fd77286c4d73afeb9d7c7c07047a0ec5dfa8b827b59787d5f' THEN statement:='UPDATE public.platform_member_operation SET fence=fence+1,lease_until=clock_timestamp()+interval ''60 seconds'',status=''RUNNING'',error_code=NULL,revision=revision+1 WHERE id=$1 AND (lease_until IS NULL OR lease_until<=clock_timestamp()) AND phase IN (''IDENTITY'',''PROJECTION'') RETURNING *';
 WHEN '91aad67f42367bbe45a0b570fbdc0d99f7681272efbdb864089aa09da9cb1462' THEN statement:='UPDATE public.platform_member_operation SET phase=$3,receipt=$4,status=''WAITING'',lease_until=NULL,revision=revision+1 WHERE id=$1 AND fence=$2 AND lease_until>clock_timestamp() RETURNING *';
 WHEN '3cbeb69a76e8caecf2cb40f3724827cb08dbe8a409d16279eb2da67a14d1d85a' THEN statement:='UPDATE public.platform_member_operation SET status=''FAILED'',error_code=''EXTERNAL_STEP_UNCONFIRMED'',lease_until=NULL,revision=revision+1 WHERE id=$1 AND fence=$2 AND lease_until>clock_timestamp() RETURNING *';
 WHEN '76d9d3d3a76246a64a56522362c6d43a7addb52aff51b3eaf685bfa13bceee4b' THEN statement:='INSERT INTO public.organization_membership(id,global_user_id,organization_id,base_role_code,status) VALUES($1,$2,$3,$4,''PENDING_PROJECTION'')';
 WHEN 'bbd507267082be39048fbf02152c2505d0fd9516b73eca92db50ae09fa16b7e2' THEN statement:='SELECT * FROM public.platform_member_invitation WHERE operation_id=$1 ORDER BY created_at DESC,id DESC FOR UPDATE';
 WHEN '3bbebbc7aa1b7254381a7078627fc7813a7753342034757d36856dd0ca40d890' THEN statement:='SELECT * FROM public.platform_member_invitation WHERE operation_id=$1 AND request_key=$2 FOR UPDATE';
 WHEN '0965d7a28ad333232e30ebf31ee48ba5f7f309b538363c477f58a3b35a0b2635' THEN statement:='INSERT INTO public.platform_member_invitation(id,operation_id,request_key,issued_by,digest,replace_requested,expires_at) VALUES($1,$2,$3,$4,$5,$6,clock_timestamp()+interval ''24 hours'') RETURNING *';
 WHEN 'e14ff021ceb4fe0c3466f82f3cf1bd40ce2a35da71cc1d280026ddb31181615f' THEN statement:='UPDATE public.platform_member_invitation SET status=''REVOKED'',revision=revision+1 WHERE operation_id=$1 AND status=''OPEN'' RETURNING *';
 WHEN 'ccad87499554ba644e3af10de6a9a731e86ddf376b39a815b05fdb867d15ff79' THEN statement:='SELECT i.*,o.organization_id,o.global_user_id,o.membership_id,o.receipt,o.phase,o.profile_code FROM public.platform_member_invitation i JOIN public.platform_member_operation o ON o.id=i.operation_id WHERE i.digest=$1 FOR UPDATE OF i,o';
 WHEN '5f95a7b27d9c0383192743a7abc208163cd9b56f09051bae9a1862360a62d5b9' THEN statement:='UPDATE public.platform_member_invitation SET exchange_digest=$2,binding_digest=$3,exchange_until=LEAST(expires_at,clock_timestamp()+interval ''10 minutes''),verified_identity=NULL,revision=revision+1 WHERE id=$1 AND status=''OPEN'' AND expires_at>clock_timestamp() RETURNING *';
 WHEN '0329b14df5b3092e7654c54deae5bd0428520027cad75b7de862e842a9fa33ab' THEN statement:='SELECT i.*,o.organization_id,o.global_user_id,o.membership_id,o.receipt,o.phase,o.profile_code FROM public.platform_member_invitation i JOIN public.platform_member_operation o ON o.id=i.operation_id WHERE i.exchange_digest=$1 AND i.binding_digest=$2 AND i.exchange_until>clock_timestamp() FOR UPDATE OF i,o';
 WHEN '7e19b1560bc7d6c84a83a1276559d2956262f346f6fd5bd3db80e7ef4385f73f' THEN statement:='UPDATE public.platform_member_invitation SET verified_identity=$2 WHERE id=$1 AND status=''OPEN'' AND expires_at>clock_timestamp() RETURNING *';
 WHEN '1d393d3380f494ccf86f9a20660a8d5dd721542c1cd8ceb4d16c173821c0857a' THEN statement:='SELECT id FROM public.platform_member_invitation WHERE id=$1 AND status=''OPEN'' AND expires_at>clock_timestamp() AND exchange_until>clock_timestamp()';
 WHEN '28b095107451426ca274868de8abbc8ddfbe949f90261f94e28631657fdfbf66' THEN statement:='UPDATE public.platform_member_invitation SET status=''USED'',accepted_at=clock_timestamp(),revision=revision+1 WHERE id=$1 AND status=''OPEN'' RETURNING *';
 WHEN '31c37c750aea05047b550ea951de00d4dffba3d16757b087b597ba156261eea6' THEN statement:='UPDATE public.platform_member_operation SET phase=''COMPLETE'',status=''COMPLETE'',revision=revision+1 WHERE id=$1 AND phase=''READY'' RETURNING *';
 WHEN '609b03763138bd57645af4eaef5aebb48f9f8a97f99cb23f51a8aa848f3b8477' THEN statement:='SELECT u.id,CASE WHEN a.global_user_id IS NOT NULL THEN ''C4G_ADMIN'' ELSE m.base_role_code END AS profile FROM public.application_session s JOIN public.global_user u ON u.id=s.global_user_id JOIN public.organization o ON o.id=$3 AND o.status=''ACTIVE'' LEFT JOIN public.platform_admin_assignment a ON a.global_user_id=u.id AND a.role_code=''C4G_ADMIN'' AND a.status=''ACTIVE'' LEFT JOIN public.organization_membership m ON m.id=s.selected_membership_id AND m.organization_id=o.id AND m.global_user_id=u.id AND m.membership_version=s.selected_membership_version AND m.status=''ACTIVE'' AND m.valid_from<=clock_timestamp() AND (m.valid_until IS NULL OR m.valid_until>clock_timestamp()) WHERE s.sid=$1 AND u.id=$2 AND u.status=''ACTIVE'' AND s.status=''ACTIVE'' AND s.expires_at>clock_timestamp() AND s.revocation_version=u.session_revocation_version AND (a.global_user_id IS NOT NULL OR (s.selected_organization_id=o.id AND m.base_role_code IN (''ORG_ADMIN'',''FUNDING_MANAGER''))) FOR SHARE OF s,u,o';
 WHEN '1dd8a88a01bb144e427baf5ecc42b547672c80e12b6abc651328bde132816c88' THEN statement:='SELECT u.id FROM public.global_user u JOIN public.organization o ON o.id=$2 AND o.status=''ACTIVE'' WHERE u.id=$1 AND u.status=''ACTIVE'' AND (EXISTS(SELECT 1 FROM public.platform_admin_assignment a WHERE a.global_user_id=u.id AND a.role_code=''C4G_ADMIN'' AND a.status=''ACTIVE'') OR EXISTS(SELECT 1 FROM public.organization_membership m WHERE m.global_user_id=u.id AND m.organization_id=o.id AND m.status=''ACTIVE'' AND m.valid_from<=clock_timestamp() AND (m.valid_until IS NULL OR m.valid_until>clock_timestamp()) AND (m.base_role_code=''ORG_ADMIN'' OR (m.base_role_code=''FUNDING_MANAGER'' AND $3=''CONTRIBUTOR'')))) FOR SHARE OF u,o';
 WHEN '751aebf23b16fecaca604dbd1539a67ccfa22dd18a8ca0d14dbbce4c06489efc' THEN statement:='SELECT id FROM public.organization_membership WHERE organization_id=$1 AND global_user_id=$2';
 WHEN '6099f0753401c75f9076ae967f0d24ab5be3a860591318ff01563716d7d8cafa' THEN statement:='SELECT id,global_user_id,organization_id,base_role_code,status,membership_version,valid_from,valid_until,status_reason FROM public.organization_membership WHERE id=$1 AND organization_id=$2 FOR UPDATE';
 WHEN '6fe19ad764d8130aef1be9f60ffa665e4e9e2f24934c60acc1f581a37f78c834' THEN statement:='SELECT * FROM public.authority_f5_state WHERE organization_id=$1 AND membership_id=$2';
 WHEN '20ff532cebacd4dd565cac383440e436f0bd2ad86276e4f58b37d8069ecab2c7' THEN statement:='UPDATE public.authority_f5_state SET authorization_version=authorization_version+1,policy_version=$3,grants=$4,assurance_requirements=$5,updated_at=clock_timestamp() WHERE organization_id=$1 AND membership_id=$2 RETURNING authorization_version';
 WHEN '34006bef4ea46fe0998e28864d6c134a3036a34957d04515e2936c36d7e7cf10' THEN statement:='UPDATE public.organization_membership SET status=$3,membership_version=membership_version+1,status_reason=$4,suspended_at=CASE WHEN $3=''SUSPENDED'' THEN clock_timestamp() ELSE suspended_at END,updated_at=clock_timestamp() WHERE id=$1 AND organization_id=$2';
 WHEN 'ec940396e7c7177bf31c25faae33bcf6a339991341605397a9906f9c4cc5caf8' THEN statement:='SELECT u.id FROM public.application_session s JOIN public.global_user u ON u.id=s.global_user_id JOIN public.platform_admin_assignment a ON a.global_user_id=u.id WHERE s.sid=$1 AND u.id=$2 AND s.status=''ACTIVE'' AND s.expires_at>clock_timestamp() AND s.revocation_version=u.session_revocation_version AND u.status=''ACTIVE'' AND a.role_code=''C4G_ADMIN'' AND a.status=''ACTIVE'' FOR SHARE OF s,u,a';
 WHEN '0d33255db2d4ac50a4e04919a8e92a2369c045e2798b2f4f9a5235a7b47ca235' THEN statement:='SELECT u.id FROM public.global_user u JOIN public.platform_admin_assignment a ON a.global_user_id=u.id WHERE u.id=$1 AND u.status=''ACTIVE'' AND a.role_code=''C4G_ADMIN'' AND a.status=''ACTIVE'' FOR SHARE OF u,a';
 WHEN 'e162963df82a58afae78a6fe8eeeea15c18265c46fe8a46d6e369552c32e51ed' THEN statement:='SELECT * FROM public.platform_onboarding_operation WHERE id=$1 FOR UPDATE';
 WHEN '0324c2ed34b9c40e295d779bad26e08e00d9c1d6e7186c5dbf6427f9cd436153' THEN statement:='SELECT * FROM public.platform_onboarding_operation WHERE requested_by=$1 AND request_key=$2 FOR UPDATE';
 WHEN '1a41fae0ff132420e42e841f49a9e63b50c816d05c36e08967ec9d0d1e6c6f2d' THEN statement:='SELECT id,organization_id,phase,status,revision,error_code,created_at FROM public.platform_onboarding_operation ORDER BY created_at DESC,id DESC LIMIT 100';
 WHEN 'd51e982744c17dd1c6c9a4b1db22dac220b35ff0d936b8d54a763134d25ca858' THEN statement:='INSERT INTO public.organization(id,legal_name,display_name,slug,type_code,status,reporting_currency,mfa_policy_code,data_residency_code) VALUES($1,$2,$3,$4,$5,''PROVISIONING'',$6,$7,$8)';
 WHEN '002e5867fe0934bcfca147efdaf194b39d61865595a8f21f17f887b370941cff' THEN statement:='INSERT INTO public.platform_onboarding_operation(id,organization_id,requested_by,request_key,intent_digest,input,global_user_id,membership_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *';
 WHEN 'aad796090e2464da30db353931c7b0c23b178e1e251c320af8efa4212e28fc00' THEN statement:='UPDATE public.platform_onboarding_operation SET fence=fence+1,lease_until=clock_timestamp()+interval ''60 seconds'',status=''RUNNING'',error_code=NULL,revision=revision+1 WHERE id=$1 AND (lease_until IS NULL OR lease_until<=clock_timestamp()) AND phase IN (''IDENTITY'',''TENANT'',''PROJECTION'') RETURNING *';
 WHEN 'a39c97ad7e6f2bcd8ecdcc75cc8d732a046ccc64ca790aa32bbcdb6a5ac3199d' THEN statement:='UPDATE public.platform_onboarding_operation SET phase=$3,receipt=$4,status=''WAITING'',lease_until=NULL,revision=revision+1 WHERE id=$1 AND fence=$2 AND lease_until>clock_timestamp() RETURNING *';
 WHEN 'ad9d3dfc57b400352dc17fd45ac2efc36a9e1826d2a0a8a778147e7ad5389eb2' THEN statement:='UPDATE public.platform_onboarding_operation SET status=''FAILED'',error_code=''EXTERNAL_STEP_UNCONFIRMED'',lease_until=NULL,revision=revision+1 WHERE id=$1 AND fence=$2 AND lease_until>clock_timestamp() RETURNING *';
 WHEN 'bcae68a5290015ec1c65026b42274c8eca9f1fe215e67afe0f87d10d21aacd20' THEN statement:='SELECT u.id,u.status,a.issuer,a.subject FROM public.global_user u LEFT JOIN public.auth_identity_ref a ON a.global_user_id=u.id WHERE lower(u.primary_email)=lower($1)';
 WHEN 'fbcf943ed84f836d1777e92bb60eb3bfc135239d3ec703a9ea3064d948fbfed6' THEN statement:='SELECT u.id,u.status,a.issuer,a.subject FROM public.global_user u JOIN public.auth_identity_ref a ON a.global_user_id=u.id WHERE u.id=$1 AND a.issuer=$2 AND a.subject=$3 FOR SHARE OF u,a';
 WHEN 'f4576bb724cc87b8239624bf2d6d44535a84e66ca960dad5d1a9908b64da338c' THEN statement:='INSERT INTO public.global_user(id,display_name,primary_email,status) VALUES($1,$2,$3,''ACTIVE'')';
 WHEN 'c10357431819a729c31c5639db4316d2f755fefee29453134f19e0787c38da86' THEN statement:='INSERT INTO public.auth_identity_ref(id,global_user_id,issuer,subject) VALUES($1,$2,$3,$4)';
 WHEN 'ead48fff5e5a6e4e40b3ca4c7adc2415d6e367430994904f62a140b43a1bf629' THEN statement:='INSERT INTO public.organization_membership(id,global_user_id,organization_id,base_role_code,status) VALUES($1,$2,$3,''ORG_ADMIN'',''PENDING_PROJECTION'')';
 WHEN '5af1f82f056cbceaf777767d398ce8692bc831cd5f304f0a0a938a818762fe3c' THEN statement:='UPDATE public.organization SET status=''ACTIVE'',updated_at=clock_timestamp() WHERE id=$1 AND status=''PROVISIONING''';
 WHEN 'd446f025f3e254b717e1c8628206f3a5bffa65bea46558443eb73d58de67449d' THEN statement:='SELECT o.id FROM public.organization o JOIN public.tenant t ON t.organization_id=o.id JOIN public.organization_provisioning p ON p.organization_id=o.id AND p.tenant_id=t.tenant_id JOIN public.tenant_workload_binding w ON w.tenant_id=t.tenant_id AND w.workload=''API'' JOIN public.organization_connection c ON c.tenant_id=t.tenant_id JOIN public.tenant_schema_state s ON s.tenant_id=t.tenant_id WHERE o.id=$1 AND o.status IN (''PROVISIONING'',''ACTIVE'') AND p.status=''READY'' AND c.operational_state=''AVAILABLE'' AND s.compatibility_state=''COMPATIBLE'' AND w.lifecycle_status=''AVAILABLE'' AND w.compatibility_status=''COMPATIBLE'' AND w.provisioning_status=''READY'' FOR SHARE OF o,p,w,c,s';
 WHEN '889e8aea4843286103312a3dbff38e7a061524b88f882f9673923a25b7c9119a' THEN statement:='SELECT id FROM public.organization WHERE id=$1 AND status=''ACTIVE'' FOR SHARE';
 WHEN 'bbebf0bd6e9dfed8ab3bf7e65331bfbee3c52d7ffe3d9fbb71b36752f8c5ac65' THEN statement:='SELECT * FROM public.platform_onboarding_invitation WHERE operation_id=$1 ORDER BY created_at DESC,id DESC FOR UPDATE';
 WHEN 'ce77e0c4eec6b7dcd9e26bba0036d2921f0420b9c29b537acaf81d135ab2703f' THEN statement:='SELECT * FROM public.platform_onboarding_invitation WHERE operation_id=$1 AND request_key=$2 FOR UPDATE';
 WHEN '688153fb08bb914e439a125ae1557868515491b0fe4f05a887dcb088c24b011d' THEN statement:='INSERT INTO public.platform_onboarding_invitation(id,operation_id,request_key,issued_by,digest,replace_requested,expires_at) VALUES($1,$2,$3,$4,$5,$6,clock_timestamp()+interval ''24 hours'') RETURNING *';
 WHEN '5c5afb2bf7901dd927f273750281087f2924ac5e752363412745ca5ed4fc5754' THEN statement:='UPDATE public.platform_onboarding_invitation SET status=''REVOKED'',revision=revision+1 WHERE operation_id=$1 AND status=''OPEN'' RETURNING *';
 WHEN 'c7964f5fc1d62df6b3c911623a04fa2816ac072380b047c551aada2d6305d560' THEN statement:='SELECT i.*,o.organization_id,o.global_user_id,o.membership_id,o.receipt,o.phase FROM public.platform_onboarding_invitation i JOIN public.platform_onboarding_operation o ON o.id=i.operation_id WHERE i.digest=$1 FOR UPDATE OF i,o';
 WHEN 'f4005b94fc9fa739d45a957f7ed218ccc806534bc0ad52c5b357a2c5e553dad6' THEN statement:='UPDATE public.platform_onboarding_invitation SET exchange_digest=$2,binding_digest=$3,exchange_until=LEAST(expires_at,clock_timestamp()+interval ''10 minutes''),verified_identity=NULL,revision=revision+1 WHERE id=$1 AND status=''OPEN'' AND expires_at>clock_timestamp() RETURNING *';
 WHEN '8e5e965443185339c99d6eeb6f78f0218faf25a17f6d4df8eba7d8035fca46f6' THEN statement:='SELECT i.*,o.organization_id,o.global_user_id,o.membership_id,o.receipt,o.phase FROM public.platform_onboarding_invitation i JOIN public.platform_onboarding_operation o ON o.id=i.operation_id WHERE i.exchange_digest=$1 AND i.binding_digest=$2 AND i.exchange_until>clock_timestamp() FOR UPDATE OF i,o';
 WHEN '8fc83302383109da7a7676743af06cba0ca326ab009aacf78e5d000757027f5e' THEN statement:='UPDATE public.platform_onboarding_invitation SET verified_identity=$2 WHERE id=$1 AND status=''OPEN'' AND expires_at>clock_timestamp() RETURNING *';
 WHEN '06a33a3e606c6deddca669bb4ea1c154da95784d63342138407469eb79f5584d' THEN statement:='SELECT id FROM public.platform_onboarding_invitation WHERE id=$1 AND status=''OPEN'' AND expires_at>clock_timestamp() AND exchange_until>clock_timestamp()';
 WHEN '331264f67b8c5f6e320b829d86c8379f477a60bcb00524b8458d6204f6f0690e' THEN statement:='SELECT * FROM public.organization_membership WHERE id=$1 AND organization_id=$2 AND global_user_id=$3 FOR UPDATE';
 WHEN 'c56db699bebf10af4ed9307cfc5a889986ac25662a6f1903275a9e26feb19c8b' THEN statement:='UPDATE public.organization_membership SET status=''ACTIVE'',activated_at=clock_timestamp(),membership_version=membership_version+1,updated_at=clock_timestamp() WHERE id=$1 AND organization_id=$2 AND status=''PENDING_PROJECTION'' RETURNING *';
 WHEN '78a1107c0c941d8205839298cc02d258312ff6bbcef4691f8d6532f61a5e059f' THEN statement:='INSERT INTO public.authority_f5_state(organization_id,membership_id,authorization_version,policy_version,grants,assurance_requirements) VALUES($1,$2,1,$3,$4,$5)';
 WHEN 'd06d735b6b2f983d100c91f18dd0821b6893e3d27f0c5dd0d0d2c4fb0a21e33b' THEN statement:='UPDATE public.platform_onboarding_invitation SET status=''USED'',accepted_at=clock_timestamp(),revision=revision+1 WHERE id=$1 AND status=''OPEN'' RETURNING *';
 WHEN '2acc79875bff23ae38621e0ad5f5980aed0763afe434b61cb0b81fd192f9b810' THEN statement:='UPDATE public.platform_onboarding_operation SET phase=''COMPLETE'',status=''COMPLETE'',revision=revision+1 WHERE id=$1 AND phase=''READY'' RETURNING *';
 WHEN '5d526d2c52d981c2d32635f22baec7e0b37b9a884925e463cc6d19757d6a477b' THEN statement:='SELECT * FROM audit.prepare_platform_append_v1($1::uuid,$2::text)';
