 WHEN '7a0ad1af60d4997f17bce7251cd9472066d1264518e03151e3718422073fb110' THEN statement:='SELECT guard_id,protected_operations,intention_digest,deadline,source_binding,state,reconciliation_result FROM public.authority_commit_guard WHERE organization_id=$1 AND subject_id=$2 AND idempotency_key=$3 AND source_binding->>''sourceOperation''=$4 AND $4 IN (''PQ1_DECIDE'') AND EXISTS (SELECT 1 FROM jsonb_array_elements(protected_operations) p WHERE p->>''resourceId''=$5) ORDER BY authority_epoch LIMIT 101';
 WHEN '3145e9fffbe31797ba8e70e4bc4edff3b68e5aafcdae16f8d23c256ce369476c' THEN statement:='SELECT guard_id,protected_operations,intention_digest,deadline,source_binding,state,reconciliation_result FROM public.authority_commit_guard WHERE organization_id=$1 AND subject_id=$2 AND idempotency_key=$3 AND source_binding->>''sourceOperation''=$4 AND $4 IN (''PQ1_ACTIVATE'',''PQ1_EVALUATE'') AND EXISTS (SELECT 1 FROM jsonb_array_elements(protected_operations) p WHERE p->>''resourceId''=$5) ORDER BY authority_epoch LIMIT 101';
 WHEN '2a3e17c8b67034cc6dd114982b7170f72671c98f18fd2f2ee1abc0d66a9dd67b' THEN statement:='SELECT guard_id,protected_operations,intention_digest,deadline,source_binding,state,reconciliation_result FROM public.authority_commit_guard WHERE organization_id=$1 AND subject_id=$2 AND idempotency_key=$3 AND source_binding->>''sourceOperation''=$4 AND $4 IN (''PQ1_UI_CREATE_DRAFT'',''PQ1_UI_EDIT_ITEMS'',''PQ1_UI_SET_COMPETENCIES'',''PQ1_UI_SET_EXPERIENCES'',''PQ1_UI_ATTACH_EVIDENCE'',''PQ1_UI_VERIFY'',''PQ1_UI_REVOKE_VERIFICATION'',''PQ1_UI_SUBMIT'',''PQ1_UI_APPROVE'',''PQ1_UI_PUBLISH'') AND EXISTS (SELECT 1 FROM jsonb_array_elements(protected_operations) p WHERE p->>''resourceId''=$5) ORDER BY authority_epoch LIMIT 101';
 WHEN 'a7e7e9b8726f1aac3ceabfc6ed88acf7c17159470d3a26bc1fa68b85e02b1641' THEN statement:='SELECT guard_id,protected_operations,intention_digest,deadline,source_binding,state,reconciliation_result FROM public.authority_commit_guard WHERE organization_id=$1 AND subject_id=$2 AND idempotency_key=$3 AND source_binding->>''sourceOperation''=$4 AND $4 IN (''CRITERIA_SAVE'',''CRITERIA_CONFIRM'') AND EXISTS (SELECT 1 FROM jsonb_array_elements(protected_operations) p WHERE p->>''resourceId''=$5) ORDER BY authority_epoch LIMIT 101';
 WHEN '17c3e20893d26b1a0a3ebb635443d75a249bdfada989875a5ed63bc14c467416' THEN statement:='SELECT guard_id,protected_operations,intention_digest,deadline,source_binding,state,reconciliation_result FROM public.authority_commit_guard WHERE organization_id=$1 AND subject_id=$2 AND idempotency_key=$3 AND source_binding->>''sourceOperation''=$4 AND $4 IN (''PROFILE_DRAFT_CREATE'',''PROFILE_DRAFT_EDIT'',''EDITORIAL_SUBMIT'',''EDITORIAL_APPROVE'',''EDITORIAL_PUBLISH'') AND EXISTS (SELECT 1 FROM jsonb_array_elements(protected_operations) p WHERE p->>''resourceId''=$5) ORDER BY authority_epoch LIMIT 101';
    WHEN 'af4a3694165aa007e70a7d55774ceb2ad34445e7ab570a004f2f98231a71f2b9' THEN statement:='SELECT om.id AS membership_id, om.organization_id, om.membership_version, om.base_role_code, org.display_name, org.slug FROM public.organization_membership om INNER JOIN public.global_user gu ON gu.id = om.global_user_id INNER JOIN public.organization org ON org.id = om.organization_id WHERE om.global_user_id = $1 AND gu.status = ''ACTIVE'' AND org.status = ''ACTIVE'' AND om.status = ''ACTIVE'' AND om.valid_from <= $2 AND (om.valid_until IS NULL OR om.valid_until > $2) ORDER BY org.display_name ASC, org.id ASC';
    WHEN '44688132ef682495a6c44b8bf37f7c4296ced91b469fe399ea02a1f8c0b97979' THEN statement:='SELECT om.id AS membership_id, om.organization_id, om.membership_version, om.base_role_code, org.display_name, org.slug FROM public.organization_membership om INNER JOIN public.global_user gu ON gu.id = om.global_user_id INNER JOIN public.organization org ON org.id = om.organization_id WHERE om.global_user_id = $1 AND om.organization_id = $3 AND gu.status = ''ACTIVE'' AND org.status = ''ACTIVE'' AND om.status = ''ACTIVE'' AND om.valid_from <= $2 AND (om.valid_until IS NULL OR om.valid_until > $2) FOR SHARE OF gu, org, om';
    WHEN 'e25a95eb83dfe403b8fb0d2f289ede1ff3b1f1d2c87bc95479ec687ab3cd8f4a' THEN statement:='SELECT om.id AS membership_id, om.organization_id, om.membership_version, om.base_role_code, org.display_name, org.slug FROM public.organization_membership om INNER JOIN public.global_user gu ON gu.id = om.global_user_id INNER JOIN public.organization org ON org.id = om.organization_id WHERE om.id = $1 AND om.organization_id = $3 AND om.membership_version = $4 AND gu.status = ''ACTIVE'' AND org.status = ''ACTIVE'' AND om.status = ''ACTIVE'' AND om.valid_from <= $2 AND (om.valid_until IS NULL OR om.valid_until > $2) FOR SHARE OF gu, org, om';
 WHEN 'bcd937c3e242e10dc1820acd6da3f697899882c364d4708295fbfc98e4c1901a' THEN statement:='SELECT EXISTS(SELECT 1 FROM public.c4g_database_identity WHERE product_code=''C4G'' AND database_role=''CENTRAL'') AS valid';
