GRANT EXECUTE ON FUNCTION audit.append_event_v1(uuid,text,text,integer,text,text,audit.ledger_location,uuid,uuid,audit.actor_type,text,text,text,bigint,timestamptz,timestamptz,uuid,uuid,text,text,text,text,jsonb) TO c4g_authority_owner;

GRANT EXECUTE ON FUNCTION audit.prepare_platform_append_v1(uuid,text) TO c4g_authority_owner;
GRANT EXECUTE ON FUNCTION audit.append_platform_event_v1(uuid,text,text,integer,text,text,audit.ledger_location,uuid,uuid,audit.actor_type,text,text,text,bigint,timestamptz,timestamptz,uuid,uuid,text,text,text,text,jsonb) TO c4g_authority_owner;
